package br.com.unit.fisicoquimica;
import br.com.unit.fisicoquimica.model.MedicaoExperimental;import br.com.unit.fisicoquimica.service.*;import org.junit.jupiter.api.Test;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class ServicesTest {@Test void converteTemperaturas(){var s=new TemperaturaService();assertEquals(273.15,s.celsiusParaKelvin(0),.00001);assertEquals(0,s.kelvinParaCelsius(273.15),.00001);}@Test void calculaDecaimento(){var s=new DecaimentoNuclearService();assertEquals(50,s.calcularQuantidade(100,10,10),.00001);assertEquals(25,s.calcularQuantidade(100,10,20),.00001);}@Test void calculaAbsorbancia(){assertEquals(1,new ColorimetriaService().calcularAbsorbancia(100,10),.00001);}@Test void calculaEstatisticas(){var s=new EstatisticaService().calcular(List.of(new MedicaoExperimental(0,1),new MedicaoExperimental(1,2),new MedicaoExperimental(2,3),new MedicaoExperimental(3,4),new MedicaoExperimental(4,5)));assertEquals(3,s.media());assertEquals(1,s.minimo());assertEquals(5,s.maximo());}}
